{
  "nl": {
    "issue": [
      {
        "text": "占有的效力：基于合同关系等产生的占有，其使用、收益、违约责任如何适用约定与法律；恶意占有人因使用致占有物损害的赔偿责任；权利人的返还原物及孳息请求权与善意占有人的必要费用请求权；占有物毁损、灭失时保险金、赔偿金、补偿金的返还及恶意占有人的补充赔偿；占有被侵占、妨害时的保护请求权及其一年期间",
        "rules": [
          "c458-1",
          "c458-2",
          "c459-1",
          "c460-1",
          "c460-but",
          "c461-1",
          "c461-2",
          "c462-1a",
          "c462-1b",
          "c462-1c",
          "c462-2"
        ]
      }
    ],
    "conditions": [
      {
        "text": "占有是基于合同关系等产生的，且合同就使用、收益、违约责任等已有约定",
        "rules": [
          "c458-1"
        ]
      },
      {
        "text": "占有是基于合同关系等产生的，但合同没有约定或者约定不明确",
        "rules": [
          "c458-2"
        ]
      },
      {
        "text": "占有人不知道且不应当知道自己没有占有的合法根据（善意占有）；占有人知道或者应当知道自己没有合法根据（恶意占有）",
        "rules": [
          "c459-good",
          "c459-mal"
        ]
      },
      {
        "text": "占有人因使用占有的不动产或者动产，致使该物受到损害",
        "rules": [
          "c459-1"
        ]
      },
      {
        "text": "不动产或者动产被他人占有，权利人请求返还原物及其孳息",
        "rules": [
          "c460-1"
        ]
      },
      {
        "text": "善意占有人因维护占有物支出了必要费用",
        "rules": [
          "c460-but"
        ]
      },
      {
        "text": "占有的不动产或者动产毁损、灭失，占有人因此取得保险金、赔偿金或者补偿金等",
        "rules": [
          "c461-1"
        ]
      },
      {
        "text": "占有物毁损、灭失，权利人的损害未得到足够弥补，且占有人为恶意",
        "rules": [
          "c461-2"
        ]
      },
      {
        "text": "占有的不动产或者动产被侵占",
        "rules": [
          "c462-1a"
        ]
      },
      {
        "text": "存在妨害占有的行为",
        "rules": [
          "c462-1b"
        ]
      },
      {
        "text": "因侵占或者妨害占有造成损害",
        "rules": [
          "c462-1c"
        ]
      },
      {
        "text": "占有人自侵占发生之日起一年内未行使返还原物的请求权",
        "rules": [
          "c462-2"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "必要费用返还请求权仅属于善意占有人，恶意占有人无此项请求权",
        "rules": [
          "c460-but",
          "c460-malicious"
        ]
      },
      {
        "text": "有权占有人（基于所有权、他物权、租赁权等本权占有）可以拒绝权利人的返还原物请求权",
        "rules": [
          "c460-rightful"
        ]
      },
      {
        "text": "占有人返还原物的请求权自侵占发生之日起一年内未行使的，该请求权消灭",
        "rules": [
          "c462-2"
        ]
      }
    ],
    "effects": [
      {
        "text": "基于合同关系等产生的占有，有关使用、收益、违约责任等按照合同约定处理",
        "rules": [
          "c458-1"
        ]
      },
      {
        "text": "合同没有约定或者约定不明确的，依照有关法律规定处理",
        "rules": [
          "c458-2"
        ]
      },
      {
        "text": "恶意占有人应当就因使用致占有物受到的损害承担赔偿责任",
        "rules": [
          "c459-1"
        ]
      },
      {
        "text": "权利人可以请求占有人返还原物及其孳息",
        "rules": [
          "c460-1"
        ]
      },
      {
        "text": "权利人应当支付善意占有人因维护占有物支出的必要费用",
        "rules": [
          "c460-but"
        ]
      },
      {
        "text": "占有人应当将因毁损、灭失取得的保险金、赔偿金或者补偿金等返还给权利人",
        "rules": [
          "c461-1"
        ]
      },
      {
        "text": "权利人的损害未得到足够弥补的，恶意占有人还应当赔偿损失",
        "rules": [
          "c461-2"
        ]
      },
      {
        "text": "占有人有权请求侵占人返还原物",
        "rules": [
          "c462-1a"
        ]
      },
      {
        "text": "对妨害占有的行为，占有人有权请求排除妨害或者消除危险",
        "rules": [
          "c462-1b"
        ]
      },
      {
        "text": "因侵占或者妨害造成损害的，占有人有权依法请求损害赔偿",
        "rules": [
          "c462-1c"
        ]
      }
    ],
    "priority": [
      {
        "text": "基于合同关系等产生的占有，合同有约定时按约定处理，不适用有关法律规定",
        "rules": [
          "c458-1",
          "c458-2"
        ]
      },
      {
        "text": "有权占有排除权利人的返还原物及孳息请求权",
        "rules": [
          "c460-rightful",
          "c460-1"
        ]
      },
      {
        "text": "一年期间届满，占有返还请求权消灭，优先于第462条第1款的占有保护请求权",
        "rules": [
          "c462-2",
          "c462-1a"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "笔记指出：善意占有与恶意占有是对无权占有的再分类，有权占有与无权占有以是否具有本权（所有权、他物权、租赁权等）为标准；第459–462条以无权占有为典型适用场景",
        "rules": []
      },
      {
        "text": "笔记指出：无权占有人不享有留置权（第447条），该效果不在本章规定之内",
        "rules": []
      },
      {
        "text": "LEGO 卡片称“善意占有者不负赔偿责任，仅负保管义务”“善意占有不产生孳息返还义务”，与法条不符：第460条未区分善意恶意，权利人均可请求返还原物及其孳息，善意占有人的特别保护仅在于必要费用请求权",
        "rules": []
      },
      {
        "text": "LEGO 卡片称“善意占有人因重大过失致物毁损灭失仍需赔偿”，法条未作此区分，第459条仅以恶意为要件",
        "rules": []
      }
    ]
  },
